class BulkStudentImport extends Admin_Controller
{
    public function __construct()
    {
        parent::__construct();
        $this->load->helper('download');
        $this->load->helper('custom_fields');
        // application_model is already loaded in MY_Controller
        $this->load->model('student_model');
        $this->load->model('email_model');
        $this->load->model('sms_model');
        $this->load->model('parents_model');
        $this->load->library('csvimport');
    }

    public function index()
    {
        // check access permission
        if (!get_permission('student', 'is_add')) {
            access_denied();
        }

        if (is_superadmin_loggedin()) {
            $branchID = $this->input->post('branch_id');
        } else {
            $branchID = get_loggedin_branch_id();
        }
        if (isset($_POST['save'])) {
            $err_msg = "";
            $i = 0;
            $this->load->library('csvimport');
            // form validation rules
            if (is_superadmin_loggedin()) {
                $this->form_validation->set_rules('branch_id', translate('branch'), 'trim|required');
            }
            // Use a simpler validation rule for the file
            if (isset($_FILES["userfile"]) && empty($_FILES['userfile']['name'])) {
                $this->form_validation->set_message('required', 'The CSV file is required.');
                $this->form_validation->set_rules('userfile', 'CSV File', 'required');
            }
            if ($this->form_validation->run() == true) {
                $csv_array = $this->csvimport->get_array($_FILES["userfile"]["tmp_name"]);
                if ($csv_array) {
                    $columnHeaders = array('FirstName','LastName','BloodGroup','Gender','Birthday','MotherTongue','Religion','Caste','Phone','City','State','PresentAddress','PermanentAddress','CategoryID','Roll','AdmissionDate','StudentEmail','StudentPassword','GuardianName','GuardianRelation','FatherName','MotherName','GuardianOccupation','GuardianMobileNo','GuardianAddress','GuardianEmail','GuardianPassword','ClassID','SectionID');
                    $csvData = array();
                    foreach ($csv_array as $row) {
                        if ($i == 0) {
                            $csvData = array_keys($row);
                        }
                        $csv_chk = array_diff($columnHeaders, $csvData);
                        if (count($csv_chk) <= 0) {
                            if (filter_var($row['StudentEmail'], FILTER_VALIDATE_EMAIL)) {
                                // Get class and section from CSV
                                $classID = $row['ClassID'];
                                $sectionID = $row['SectionID'];
                                
                                // Check if class and section exist
                                $classExists = $this->db->where('id', $classID)->get('class')->num_rows();
                                $sectionExists = $this->db->where('id', $sectionID)->get('section')->num_rows();
                                
                                if (!$classExists || !$sectionExists) {
                                    $err_msg .= $row['FirstName'] . ' ' . $row['LastName'] . " - Import Failed: Invalid Class ID or Section ID.<br>";
                                    continue;
                                }
                                
                                // Check if student email and roll already exist
                                $r = $this->csvCheckExistsData($row['StudentEmail'], $row['Roll'], $classID, $branchID);
                                if ($r['status'] == false) {
                                    $err_msg .= $row['FirstName'] . ' ' . $row['LastName'] . " - Import Failed: " . $r['message'] . "<br>";
                                } else {
                                    $this->bulkImportStudent($row, $branchID);
                                    $i++;
                                }
                            } else {
                                $err_msg .= $row['FirstName'] . ' ' . $row['LastName'] . " - Import Failed: Invalid Email.<br>";
                            }
                        } else {
                            set_alert('error', translate('invalid_csv_file'));
                            redirect(base_url("bulkstudentimport"));
                        }
                    }
                    if ($err_msg != null) {
                        $this->session->set_flashdata('csvimport', $err_msg);
                    }
                    if ($i > 0) {
                        set_alert('success', $i . ' Students Have Been Successfully Added');
                    }
                    redirect(base_url("bulkstudentimport"));
                } else {
                    set_alert('error', translate('invalid_csv_file'));
                    redirect(base_url("bulkstudentimport"));
                }
            }
        }
        $this->data['title'] = translate('bulk_student_import');
        $this->data['branch_id'] = isset($branchID) ? $branchID : '';
        $this->data['sub_page'] = 'bulkstudentimport/index';
        $this->data['main_menu'] = 'admission';
        $this->data['headerelements'] = array(
            'css' => array(
                'vendor/dropify/css/dropify.min.css',
            ),
            'js' => array(
                'vendor/dropify/js/dropify.min.js',
            ),
        );
        $this->load->view('layout/index', $this->data);
    }

    // CSV file sample download
    public function csv_Sampledownloader()
    {
        $this->load->helper('download');
        $data = file_get_contents('uploads/bulk_student_sample.csv');
        force_download("bulk_student_sample.csv", $data);
    }

    // check student email already exists
    private function csvCheckExistsData($email, $roll, $classID, $branchID)
    {
        $array = array();
        // verify existing email
        $this->db->where('email', $email);
        $query = $this->db->get('student');
        if ($query->num_rows() > 0) {
            $array['status'] = false;
            $array['message'] = "Email already exists.";
            return $array;
        }

        // verify existing roll
        $this->db->where(array('roll' => $roll, 'class_id' => $classID, 'branch_id' => $branchID));
        $query = $this->db->get('enroll');
        if ($query->num_rows() > 0) {
            $array['status'] = false;
            $array['message'] = "Roll already exists in this class.";
            return $array;
        }

        $array['status'] = true;
        return $array;
    }

    // bulk student import function
    private function bulkImportStudent($row, $branchID)
    {
        if (!is_array($row)) {
            return false;
        }

        // Get class and section from CSV
        $classID = $row['ClassID'];
        $sectionID = $row['SectionID'];

        $getParent = $this->db->select('id')->where(array('branch_id' => $branchID, 'email' => $row['GuardianEmail']))->get('parent')->row_array();
        if ($getParent && is_array($getParent)) {
            $parentID = $getParent['id'];
        } else {
            // add new guardian all information in db
            $arrayParent = array(
                'name' => isset($row['GuardianName']) ? $row['GuardianName'] : '',
                'relation' => isset($row['GuardianRelation']) ? $row['GuardianRelation'] : '',
                'father_name' => isset($row['FatherName']) ? $row['FatherName'] : '',
                'mother_name' => isset($row['MotherName']) ? $row['MotherName'] : '',
                'occupation' => isset($row['GuardianOccupation']) ? $row['GuardianOccupation'] : '',
                'mobileno' => isset($row['GuardianMobileNo']) ? $row['GuardianMobileNo'] : '',
                'address' => isset($row['GuardianAddress']) ? $row['GuardianAddress'] : '',
                'email' => isset($row['GuardianEmail']) ? $row['GuardianEmail'] : '',
                'branch_id' => $branchID,
                'photo' => 'defualt.png',
            );
            $this->db->insert('parent', $arrayParent);
            $parentID = $this->db->insert_id();
            $parent_credential = array(
                'username' => isset($row["GuardianEmail"]) ? $row["GuardianEmail"] : '',
                'role' => 6,
                'user_id' => $parentID,
                'password' => $this->app_lib->pass_hashed(isset($row["GuardianPassword"]) ? $row["GuardianPassword"] : ''),
            );
            $this->db->insert('login_credential', $parent_credential);
        }

        $inser_data1 = array(
            'first_name' => isset($row['FirstName']) ? $row['FirstName'] : '',
            'last_name' => isset($row['LastName']) ? $row['LastName'] : '',
            'blood_group' => isset($row['BloodGroup']) ? $row['BloodGroup'] : '',
            'gender' => isset($row['Gender']) ? $row['Gender'] : '',
            'birthday' => date("Y-m-d", strtotime(isset($row['Birthday']) ? $row['Birthday'] : date('Y-m-d'))),
            'mother_tongue' => isset($row['MotherTongue']) ? $row['MotherTongue'] : '',
            'religion' => isset($row['Religion']) ? $row['Religion'] : '',
            'parent_id' => $parentID,
            'caste' => isset($row['Caste']) ? $row['Caste'] : '',
            'mobileno' => isset($row['Phone']) ? $row['Phone'] : '',
            'city' => isset($row['City']) ? $row['City'] : '',
            'state' => isset($row['State']) ? $row['State'] : '',
            'current_address' => isset($row['PresentAddress']) ? $row['PresentAddress'] : '',
            'permanent_address' => isset($row['PermanentAddress']) ? $row['PermanentAddress'] : '',
            'category_id' => isset($row['CategoryID']) ? $row['CategoryID'] : '',
            'admission_date' => date("Y-m-d", strtotime(isset($row['AdmissionDate']) ? $row['AdmissionDate'] : date('Y-m-d'))),
            'register_no' => substr(app_generate_hash(), 4, 7),
            'photo' => 'defualt.png',
            'email' => isset($row['StudentEmail']) ? $row['StudentEmail'] : '',
        );
        //save all student information in the database file
        $this->db->insert('student', $inser_data1);
        $studentID = $this->db->insert_id();
        //save student login credential
        $inser_data2 = array(
            'username' => isset($row["StudentEmail"]) ? $row["StudentEmail"] : '',
            'role' => 7,
            'user_id' => $studentID,
            'password' => $this->app_lib->pass_hashed(isset($row["StudentPassword"]) ? $row["StudentPassword"] : ''),
        );
        $this->db->insert('login_credential', $inser_data2);

        // Get the current active session ID
        $session_id = get_session_id();
        
        // Log the session ID for debugging
        error_log("Using session ID for enrollment: " . $session_id);

        //save student enroll information in the database file
        $arrayEnroll = array(
            'student_id' => $studentID,
            'class_id' => $classID,
            'section_id' => $sectionID,
            'branch_id' => $branchID,
            'roll' => isset($row['Roll']) ? $row['Roll'] : '',
            'session_id' => $session_id,
        );
        
        // Log the enrollment data
        error_log("Enrollment data: " . json_encode($arrayEnroll));
        
        // Insert enrollment record
        $this->db->insert('enroll', $arrayEnroll);
        
        // Log the result of the insertion
        error_log("Enrollment insertion result: " . ($this->db->affected_rows() > 0 ? "Success" : "Failed"));
    }

    // CSV file upload validation callback
    public function handle_csv_upload()
    {
        if (isset($_FILES["userfile"]) && empty($_FILES['userfile']['name'])) {
            $this->form_validation->set_message("handle_csv_upload", "The CSV file is required.");
            return false;
        } else {
            $temp_file = $_FILES["userfile"]["tmp_name"];
            $file_name = $_FILES["userfile"]["name"];
            $file_size = $_FILES["userfile"]["size"];
            $file_type = $_FILES["userfile"]["type"];
            $allowed_extension = array('csv');
            $ext = pathinfo($file_name, PATHINFO_EXTENSION);
            if (!in_array($ext, $allowed_extension)) {
                $this->form_validation->set_message("handle_csv_upload", "Invalid file extension, only CSV file is allowed.");
                return false;
            }
            return true;
